<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {api} from './api'
const emit=defineEmits<{error:[string]}>()
const models=ref<any[]>([]),jobs=ref<any[]>([]),selected=ref<any>(null),document=ref(''),tested=ref(false),licensed=ref(false),busy=ref(false),message=ref('')
let timer:ReturnType<typeof setInterval>|undefined
async function load(){const data=await api('speech-models/manage');models.value=data.models;jobs.value=data.jobs}
onMounted(()=>{load().catch(e=>emit('error',String(e)));timer=setInterval(()=>load().catch(()=>{}),5000)})
onBeforeUnmount(()=>clearInterval(timer))
function select(item:any){selected.value=item;document.value=JSON.stringify(item.manifest,null,2);tested.value=false;licensed.value=false;message.value=''}
function newVersion(){if(!selected.value)return;const next=JSON.parse(document.value);next.version='custom-'+Date.now();document.value=JSON.stringify(next,null,2);selected.value=null;tested.value=false;licensed.value=false}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await action();await load()}catch(e){emit('error',String(e))}finally{busy.value=false}}
async function save(){await run(async()=>{const manifest=JSON.parse(document.value);await api('speech-models','POST',manifest);await load();const item=models.value.find(v=>v.manifest.id===manifest.id&&v.manifest.version===manifest.version);if(item)select(item);message.value='Draft salvat. Copiază fișierele și verifică compatibilitatea înainte de publicare.'})}
async function action(kind:string){if(!selected.value)return;await run(async()=>{const m=selected.value.manifest;await api('speech-models/'+m.id+'/'+m.version+'/'+kind,'POST',kind==='publish'?{compatibility_tested:tested.value,redistribution_allowed:licensed.value}:{});message.value=kind==='publish'?'Versiune publicată. Actualizează catalogul pe telefon.':'Operație pusă în coadă.'})}
async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);if(!selected.value||!files.length)return
 await run(async()=>{for(const artifact of selected.value.manifest.files){const matches=files.filter(f=>(f.webkitRelativePath||f.name)===artifact.path||(f.webkitRelativePath||f.name).endsWith('/'+artifact.path));if(matches.length!==1)throw new Error('Selectează directorul care conține exact fișierul '+artifact.path);const file=matches[0];if(file.size!==artifact.size)throw new Error('Dimensiune greșită: '+artifact.path);let offset=0;while(offset<file.size){message.value='Upload '+artifact.path+' · '+Math.round(offset*100/file.size)+'%';const response=await fetch('/v1/speech-models/blobs/'+artifact.sha256+'?offset='+offset,{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:file.slice(offset,offset+8*1024*1024)});const data=await response.json();if(response.status===409&&Number.isSafeInteger(data.uploaded)&&data.uploaded>=0&&data.uploaded<=file.size){offset=data.uploaded;continue}if(!response.ok)throw new Error(data.error||'Upload eșuat');if(!Number.isSafeInteger(data.uploaded)||data.uploaded<=offset||data.uploaded>file.size)throw new Error('Offset invalid');offset=data.uploaded}}message.value='Fișiere încărcate și verificate SHA-256.'});input.value=''
}
</script>
<template><section class="paper"><h2>Modele vocale locale · copii WiseMED AI</h2><p>Telefoanele încearcă sursa originală, apoi copia verificată de aici. Catalogul este comun organizațiilor acestei instanțe; modificările sunt rezervate administratorului instanței.</p><p>Sursele cu track=true se verifică zilnic după publicare. Reviziile noi sunt copiate într-un draft. Publicarea cere verificarea compatibilității; schimbarea structurii cere un manifest nou.</p><Button label="Reîncarcă" text @click="load().catch(e=>emit('error',String(e)))"/><div class="table-wrap"><table><thead><tr><th>Model / versiune</th><th>Motor</th><th>Copie locală</th><th>Publicare</th></tr></thead><tbody><tr v-for="item in models" :key="item.manifest.id+item.manifest.version"><td><Button text :label="item.manifest.label" @click="select(item)"/><br/><small>{{item.manifest.id}} · {{item.manifest.version}}</small></td><td>{{item.manifest.runtime}}<br/>{{item.manifest.platforms.join(', ')}}</td><td>{{item.mirrored_files}} / {{item.manifest.files.length}} fișiere</td><td>{{item.published?'Publicată':'Draft / versiune anterioară'}}</td></tr></tbody></table></div></section>
<section class="paper"><h2>Adaugă model sau versiune compatibilă</h2><p>Selectează un model existent ca exemplu. Formatele acceptate: sherpa-onnx-2.0.1 (Whisper ori Parakeet TDT v3 cu BPE), whisperkit-9f99b5c, fluidaudio-503b4bd. PyTorch și GGUF necesită conversie înainte de utilizare.</p><Button label="Creează versiune din modelul selectat" text :disabled="!selected||busy" @click="newVersion"/><label>Manifest JSON · ID, versiune, format, surse, fișiere și SHA-256<Textarea v-model="document" rows="14" style="width:100%;font-family:monospace"/></label><Button label="Salvează draftul" :disabled="busy||!document" @click="save"/>
<template v-if="selected"><div class="actions"><Button label="Copiază / repară fișierele pe server" :disabled="busy" @click="action('mirror')"/><Button label="Verifică revizia nouă la sursă" :disabled="busy" @click="action('check-update')"/></div><p>Dacă sursa nu mai este disponibilă, încarcă fișiere din calculator. Uploadul se reia de la offsetul confirmat și verifică hash-ul la final.</p><label>Încarcă directorul modelului<input type="file" multiple webkitdirectory :disabled="busy" @change="upload"/></label><label>Încarcă fișiere ONNX individuale<input type="file" multiple :disabled="busy" @change="upload"/></label><label class="check"><input type="checkbox" v-model="tested"/> Am verificat compatibilitatea și transcrierea română pe platformele declarate.</label><label class="check"><input type="checkbox" v-model="licensed"/> Licența permite redistribuirea fișierelor prin WiseMED AI.</label><Button label="Publică această versiune" :disabled="busy||!tested||!licensed" @click="action('publish')"/></template><p role="status">{{message}}</p></section>
<section class="paper"><h2>Copieri și verificări recente</h2><div class="table-wrap"><table><thead><tr><th>Model</th><th>Operație</th><th>Stare</th><th>Progres</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{job.model_id}}<br/><small>{{job.version}}</small></td><td>{{job.kind}}</td><td>{{job.state}}<br/>{{job.error_code}}</td><td>{{job.completed_files}} / {{job.total_files}}</td></tr></tbody></table></div></section></template>
